package com.portfolio.deployops.service;
import com.portfolio.deployops.domain.*;
import com.portfolio.deployops.repository.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.time.LocalDateTime;
import java.util.*;
import org.junit.jupiter.api.*;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
class NexusRestoreRecoveryCheckTest {
 NexusRestoreRequestRepository repo; ExecutionGuardRepository guard; NexusRestoreJobGateway gateway; AuditLogService audit; NexusRestoreService service; NexusRestoreRequest request; NexusRestoreRecoveryCheck check;
 @BeforeEach void setup(){repo=mock(NexusRestoreRequestRepository.class);guard=mock(ExecutionGuardRepository.class);gateway=mock(NexusRestoreJobGateway.class);audit=mock(AuditLogService.class);service=new NexusRestoreService(repo,mock(NexusBackupRequestRepository.class),guard,mock(DeployRequestRepository.class),gateway,audit);
 request=new NexusRestoreRequest();request.setId(2L);request.setBackupRequestId(2L);request.setManifestSha256("a".repeat(64));request.setStatus("RECOVERY_REQUIRED");request.setSubmitted(true);request.setActiveCheckId(7L);
 check=new NexusRestoreRecoveryCheck();check.setId(7L);check.setRequestId(2L);check.setStatus("SUBMITTED");when(repo.find(2L)).thenReturn(Optional.of(request));when(repo.findCheck(7L)).thenReturn(Optional.of(check));when(guard.lockSingleton()).thenReturn(1);when(guard.nexusRestoreOwner()).thenReturn(2L);when(gateway.ready()).thenReturn(true);when(repo.finishCheck(any())).thenReturn(1);when(repo.result(any())).thenReturn(1);when(repo.clearCheck(2L,7L)).thenReturn(1);when(guard.releaseNexusRestore(2L)).thenReturn(1); }
 NexusRestoreJobGateway.CheckResult result(boolean verified){return new NexusRestoreJobGateway.CheckResult(2,"a".repeat(64),verified?"VERIFIED_FAILED":"UNCONFIRMED",verified?"PRECONTAINER_FAILURE_CONFIRMED":"STATE_UNCONFIRMED",verified,!verified,LocalDateTime.of(2026,10,12,1,0));}
 @Test void verifiedFailureCommitsFailedAndReleasesOnlyOnce(){service.acceptRecoveryCheck(2L,7L,result(true));assertThat(request.getStatus()).isEqualTo("FAILED");assertThat(request.getStage()).isEqualTo("DONE");verify(guard).releaseNexusRestore(2L);service.acceptRecoveryCheck(2L,7L,result(true));verify(audit,times(1)).recordCurrentRequired(anyString(),anyString(),anyString(),anyString(),any());}
 @Test void unconfirmedKeepsReservationAndAllowsOnlyExplicitNewCheck(){service.acceptRecoveryCheck(2L,7L,result(false));verify(repo).clearCheck(2L,7L);verify(repo,never()).result(any());verify(guard,never()).releaseNexusRestore(any());assertThat(request.getStatus()).isEqualTo("RECOVERY_REQUIRED");}
 @Test void staleResultCannotAuditOrRelease(){request.setActiveCheckId(8L);service.acceptRecoveryCheck(2L,7L,result(true));verifyNoInteractions(audit);verify(repo,never()).finishCheck(any());verify(guard,never()).releaseNexusRestore(any());}
 @Test void activeAndCasLosersRejectDuplicateRequest(){assertThatThrownBy(()->service.requestRecoveryCheck(2L,20L)).isInstanceOf(org.springframework.web.server.ResponseStatusException.class);request.setActiveCheckId(null);when(repo.insertCheck(any())).thenAnswer(c->{((NexusRestoreRecoveryCheck)c.getArgument(0)).setId(9L);return 1;});when(repo.activateCheck(2L,9L)).thenReturn(0);assertThatThrownBy(()->service.requestRecoveryCheck(2L,20L)).isInstanceOf(org.springframework.web.server.ResponseStatusException.class);verifyNoInteractions(audit);}
 @Test void requiredAuditFailureNeverReleases(){doThrow(new IllegalStateException("AUDIT_FAILED")).when(audit).recordCurrentRequired(anyString(),anyString(),anyString(),anyString(),any());assertThatThrownBy(()->service.acceptRecoveryCheck(2L,7L,result(true))).isInstanceOf(IllegalStateException.class);verify(repo,never()).result(any());verify(guard,never()).releaseNexusRestore(any());}
 @Test void missingPublishedResultDoesNotRepublishSubmittedToken()throws Exception{var svc=mock(NexusRestoreService.class);when(svc.unfinishedChecks()).thenReturn(List.of(check));when(svc.require(2L)).thenReturn(request);when(svc.unfinished()).thenReturn(List.of(request));var reconciler=new NexusRestoreReconciler(svc,gateway);reconciler.poll();reconciler.poll();verify(gateway,never()).submitRecoveryCheck(anyLong(),anyLong(),anyLong(),anyString());verify(gateway,never()).result(anyLong());verify(gateway,times(2)).recoveryCheckResult(2L,7L);}
 ObjectNode json(){var n=new ObjectMapper().createObjectNode();n.put("schema",1);n.put("requestId",2);n.put("checkId",7);n.put("backupRequestId",2);n.put("manifestSha256","a".repeat(64));n.put("status","VERIFIED_FAILED");n.put("reasonCode","PRECONTAINER_FAILURE_CONFIRMED");n.put("originalProjectionPreserved",true);n.put("mutationUncertain",false);n.put("completedAt","2026-10-12T01:00:00Z");return n;}
 @Test void strictResultAcceptsOnlyFailedProof()throws Exception{assertThat(NexusRestoreJobGateway.parseCheck(json(),2,7).status()).isEqualTo("VERIFIED_FAILED");for(String key:List.of("schema","requestId","checkId","backupRequestId","manifestSha256","status","reasonCode","originalProjectionPreserved","mutationUncertain","completedAt")){var n=json();n.remove(key);assertThatThrownBy(()->NexusRestoreJobGateway.parseCheck(n,2,7)).isInstanceOf(java.io.IOException.class);}for(String status:List.of("HEALTH_READY","COMPLETED","FAILED")){var n=json();n.put("status",status);assertThatThrownBy(()->NexusRestoreJobGateway.parseCheck(n,2,7)).isInstanceOf(java.io.IOException.class);}var n=json();n.put("mutationUncertain",true);assertThatThrownBy(()->NexusRestoreJobGateway.parseCheck(n,2,7)).isInstanceOf(java.io.IOException.class);}

 @Test void historicalPrimaryCannotBypassUnconfirmedCheck(){request.setActiveCheckId(null);request.setLastCheckStatus("UNCONFIRMED");service.accept(2L,null);verify(repo,never()).result(any());verifyNoInteractions(audit);verify(guard,never()).releaseNexusRestore(any());}
}
